import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { convertLegal, findPlaceholders } from '../src/legal-markdown';

/**
 * `pnpm legal:generate` — writes packages/shared/src/legal.generated.ts from docs/legal/*.md so the app shows exactly what the
 * website shows. `pnpm legal:placeholders` — lists every [bracketed] item FTech or the lawyer still has to fill in or decide.
 * Run `legal:generate` after every change to a legal markdown file (a test fails when the generated file is out of date).
 */
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');
const FILES = { privacy: 'privacy-notice.md', terms: 'terms-of-service.md', refund: 'refund-policy.md' } as const;
const read = (name: string) => readFileSync(path.join(root, 'docs/legal', name), 'utf8');
const source = { privacy: read(FILES.privacy), terms: read(FILES.terms), refund: read(FILES.refund) };

if (process.argv.includes('--placeholders')) {
  let total = 0;
  for (const [key, file] of Object.entries(FILES)) {
    const items = findPlaceholders(source[key as keyof typeof FILES]);
    total += items.length;
    console.log(`\n${file}: ${items.length} to fill in or decide`);
    for (const i of items) console.log(`  line ${String(i.line).padStart(3)}  [${i.text}]`);
  }
  console.log(`\n${total} placeholders in total. Lawyer review is still needed before launch.`);
} else {
  const out = path.join(root, 'packages/shared/src/legal.generated.ts');
  const body = JSON.stringify(convertLegal(source), null, 2);
  writeFileSync(
    out,
    `// GENERATED by \`pnpm legal:generate\` from docs/legal/*.md — do not edit by hand.\nimport type { GeneratedLegal } from './legal-markdown';\n\nexport const LEGAL_GENERATED: GeneratedLegal = ${body};\n`,
  );
  console.log(`Wrote ${path.relative(root, out)}`);
}
